import React, { useState, useMemo } from 'react';
import { Terminal, ShieldAlert, Search, RefreshCw, AlertTriangle, Cpu, TerminalSquare } from 'lucide-react';

interface DiagnosticsTerminalProps {
  logs: string[];
  onRefresh: () => void;
  loading: boolean;
}

export function DiagnosticsTerminal({ logs, onRefresh, loading }: DiagnosticsTerminalProps) {
  const [search, setSearch] = useState('');
  const [selectedComponent, setSelectedComponent] = useState<string>('ALL');

  // Filter logs dynamically in memory
  const filteredLogs = useMemo(() => {
    return logs.filter(log => {
      const matchesSearch = !search || log.toLowerCase().includes(search.toLowerCase());
      
      let matchesComponent = true;
      if (selectedComponent !== 'ALL') {
        matchesComponent = log.includes(`[${selectedComponent}]`) || log.toLowerCase().includes(`"${selectedComponent.toLowerCase()}"`);
      }
      
      return matchesSearch && matchesComponent;
    });
  }, [logs, search, selectedComponent]);

  const components = ['ALL', 'SYSTEM', 'DB', 'API', 'SPLIT_ENGINE', 'CACHE', 'PNR', 'LIVE_TRACK'];

  // Helper to parse log message highlights
  const formatLogLine = (line: string) => {
    try {
      // If it is stored as structured Winston JSON
      const parsed = JSON.parse(line);
      const time = parsed.timestamp ? new Date(parsed.timestamp).toLocaleTimeString() : '';
      const level = (parsed.level || 'error').toUpperCase();
      const comp = parsed.component || 'SYSTEM';
      const msg = parsed.message || '';

      const levelColor = level === 'ERROR' ? 'text-red-400 font-bold' : level === 'WARN' ? 'text-amber-400 font-bold' : 'text-cyan-400';
      const compColor = comp === 'DB' ? 'text-purple-400' : comp === 'SPLIT_ENGINE' ? 'text-indigo-400' : comp === 'API' ? 'text-blue-400' : 'text-zinc-400';

      return (
        <span className="block py-1 hover:bg-zinc-900/50 rounded px-2 font-mono text-[12px] leading-relaxed transition-colors">
          <span className="text-zinc-600">[{time}]</span>{' '}
          <span className={levelColor}>[{level}]</span>{' '}
          <span className={`${compColor} font-semibold`}>[{comp}]</span>{' '}
          <span className="text-zinc-200">{msg}</span>
        </span>
      );
    } catch {
      // Fallback if the line is raw string text
      let levelColor = 'text-red-400';
      if (line.includes('[WARN]')) levelColor = 'text-amber-400';
      else if (line.includes('[INFO]')) levelColor = 'text-cyan-400';

      return (
        <span className="block py-1 hover:bg-zinc-900/50 rounded px-2 font-mono text-[12px] leading-relaxed transition-colors text-zinc-300">
          <span className="text-zinc-500 font-sans mr-2">❯</span>
          <span className={levelColor}>{line}</span>
        </span>
      );
    }
  };

  return (
    <div className="bg-card border border-zinc-800 rounded-2xl p-6 backdrop-blur-md bg-gradient-to-br from-zinc-950 to-zinc-900/90 shadow-2xl space-y-5 relative overflow-hidden transition-all duration-300">
      <div className="absolute inset-0 bg-gradient-to-tr from-purple-500/2 via-transparent to-transparent pointer-events-none" />
      
      {/* Terminal Title Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center border-b border-zinc-800/80 pb-4 gap-4">
        <div className="flex items-center gap-2.5">
          <div className="p-2 bg-zinc-800/80 rounded-lg text-cyan-400 shadow-[0_0_10px_rgba(34,211,238,0.15)] animate-pulse">
            <Terminal size={18} />
          </div>
          <div>
            <h3 className="font-semibold text-zinc-100 text-sm md:text-base flex items-center gap-2 font-mono tracking-wider">
              DIAGNOSTIC LOGS TERMINAL
            </h3>
            <p className="text-zinc-500 text-xs font-mono">Buffered tail logs | logs/error-today.log</p>
          </div>
        </div>

        <button 
          onClick={onRefresh} 
          disabled={loading}
          className="px-3.5 py-1.5 bg-zinc-800 hover:bg-zinc-700 text-zinc-300 rounded-lg text-xs font-semibold flex items-center gap-1.5 transition border border-zinc-700 hover:border-zinc-600 disabled:opacity-50"
        >
          <RefreshCw size={12} className={loading ? 'animate-spin' : ''} />
          REFRESH BUFFER
        </button>
      </div>

      {/* Control Console Filters */}
      <div className="flex flex-col lg:flex-row gap-3">
        <div className="relative flex-1">
          <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500" />
          <input 
            type="text" 
            value={search} 
            onChange={e => setSearch(e.target.value)} 
            placeholder="Filter logs by search term..."
            className="w-full pl-9 pr-4 py-2 bg-zinc-900/80 border border-zinc-800 rounded-lg text-xs text-zinc-300 focus:outline-none focus:border-zinc-600 focus:ring-1 focus:ring-zinc-700 transition" 
          />
        </div>

        <div className="flex flex-wrap gap-1.5 items-center">
          <span className="text-[10px] text-zinc-500 font-mono uppercase font-bold mr-1.5">Component:</span>
          {components.map(comp => (
            <button
              key={comp}
              onClick={() => setSelectedComponent(comp)}
              className={`px-2.5 py-1 rounded text-[10px] font-mono font-medium transition ${selectedComponent === comp ? 'bg-cyan-900/30 text-cyan-400 border border-cyan-500/30' : 'bg-zinc-900/60 text-zinc-400 border border-zinc-850 hover:bg-zinc-800/80'}`}
            >
              {comp}
            </button>
          ))}
        </div>
      </div>

      {/* Terminal Visual Display Box */}
      <div className="bg-black/95 border border-zinc-850 rounded-xl p-4 min-h-[350px] max-h-[500px] overflow-y-auto relative shadow-inner">
        <div className="absolute inset-0 bg-grid-pattern pointer-events-noneopacity-5" />
        
        {loading ? (
          <div className="absolute inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-10">
            <Loader size={24} />
          </div>
        ) : null}

        <div className="space-y-1 font-mono">
          {filteredLogs.length > 0 ? (
            filteredLogs.map((line, idx) => (
              <div key={idx}>
                {formatLogLine(line)}
              </div>
            ))
          ) : (
            <div className="flex flex-col items-center justify-center text-center text-zinc-500 py-16 space-y-2">
              <ShieldAlert size={28} className="text-zinc-600 animate-bounce" />
              <p className="text-xs">Console buffer matches zero current errors.</p>
              <p className="text-[10px] text-zinc-650">Verify filter strings or check system health overview.</p>
            </div>
          )}
        </div>
      </div>

      {/* Console details footer */}
      <div className="flex justify-between items-center text-[10px] text-zinc-600 font-mono pt-1">
        <span className="flex items-center gap-1">
          <TerminalSquare size={12} className="text-cyan-500" />
          Virtual Shell Connected | Active Log Stream
        </span>
        <span>Filtered: {filteredLogs.length} / {logs.length} lines</span>
      </div>
    </div>
  );
}

function Loader({ size }: { size: number }) {
  return (
    <div className="flex flex-col items-center gap-2 text-cyan-400">
      <RefreshCw size={size} className="animate-spin" />
      <span className="text-[10px] font-mono tracking-widest animate-pulse uppercase">Fetching Log Stream</span>
    </div>
  );
}
