"use client";

import React, { useEffect, useState, useCallback } from "react";
import { ShieldAlert, LogOut, ArrowLeft } from "lucide-react";
import { useRouter } from "next/navigation";
import { DiagnosticsTerminal } from "../../../components/DiagnosticsTerminal";

const API = "https://railai.eshopcity.in";

export default function LogsDashboard() {
  const [logs, setLogs] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const router = useRouter();

  const [isAdmin, setIsAdmin] = useState<boolean | null>(null);

  const fetchLogs = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      const userStr = localStorage.getItem("user");
      if (!userStr) {
        setIsAdmin(false);
        router.push("/");
        return;
      }
      const user = JSON.parse(userStr);
      if (!user.isAdmin) {
        setIsAdmin(false);
        router.push("/");
        return;
      }

      const res = await fetch(`${API}/api/admin/diagnostics`, {
        headers: { "x-user-id": user.id }
      });

      if (res.status === 401 || res.status === 403) {
        setIsAdmin(false);
        router.push("/");
        return;
      }

      const json = await res.json();
      if (json.success) {
        setLogs(json.logs || []);
        setIsAdmin(true);
      } else {
        setError(json.error || "Failed to load diagnostic logs.");
      }
    } catch (err: any) {
      setError("Network error fetching diagnostic logs.");
    } finally {
      setLoading(false);
    }
  }, [router]);

  useEffect(() => {
    fetchLogs();
  }, [fetchLogs]);

  return (
    <div className="min-h-screen bg-app text-main font-sans">
      {/* Header */}
      <div className="sticky top-0 z-40 bg-app/80 backdrop-blur-md border-b border-zinc-800">
        <div className="max-w-7xl mx-auto px-4 md:px-8 py-4 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <ShieldAlert className="text-red-500 animate-pulse" size={24} />
            <div>
              <h1 className="text-xl font-bold leading-tight">System Command Center</h1>
              <p className="text-zinc-500 text-xs">Diagnostic Console · Trayago</p>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <button 
              onClick={() => router.push("/admin")} 
              className="px-3.5 py-1.5 text-xs bg-zinc-800 hover:bg-zinc-700 rounded-lg text-zinc-300 transition flex items-center gap-1.5 border border-zinc-700 hover:text-zinc-100"
            >
              <ArrowLeft size={12} /> Dashboard
            </button>
            <button
              onClick={() => { localStorage.removeItem("user"); router.push("/login"); }}
              className="px-3 py-1.5 text-xs bg-red-900/30 hover:bg-red-900/60 border border-red-800/30 text-red-400 rounded-lg transition flex items-center gap-1.5"
            >
              <LogOut size={12} /> Exit
            </button>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 md:px-8 py-8 space-y-6">
        {error ? (
          <div className="bg-red-900/10 border border-red-500/20 text-red-400 p-4 rounded-xl text-sm flex items-center gap-2">
            <ShieldAlert size={16} />
            {error}
          </div>
        ) : null}

        <DiagnosticsTerminal logs={logs} onRefresh={fetchLogs} loading={loading} />
      </div>
    </div>
  );
}
